create or replace view public.team_directory as select id, full_name, role, avatar_url from public.profiles where role in ('ceo', 'operations_manager', 'staff', 'videographer'); revoke all on public.team_directory from anon; grant select on public.team_directory to authenticated; comment on view public.team_directory is 'Display-only names, roles and photos for team members. Exposes four ' 'columns on purpose: profiles also holds phone, notification email and ' 'availability, none of which a client or a colleague needs in order to ' 'see who wrote a message. Runs with the owner''s privileges, so it is ' 'the column list that limits what is visible, not RLS.';
